#!/bin/bash
# process_csv.sh

file="$1"
if [ ! -f "$file" ]; then
  echo "File not found" >&2
  exit 1
fi

sed '/^#/d;/^$/d' "$file" | sed '1d' | awk -F, '{
  sum += $3
  count++
  if ($3 > max) { max = $3; name = $1 }
}
END {
  if (count > 0) {
    printf "Average salary: %.0f\n", sum/count
    printf "Highest salary: %d (%s)\n", max, name
    print "Employees: " count
  }
}'
